(()=>{'use strict';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const lightbox=$('#lightbox'),filmDialog=$('#film-dialog'),video=$('#full-film');let frames=[],index=0,lastTrigger=null,lightboxTrigger=null,frameSeconds=0,requestId=0;
const dataReady=fetch('photo-memoir-data.json').then(r=>{if(!r.ok)throw Error('图片索引加载失败');return r.json()}).then(data=>{frames=data.frames;return frames});
function lock(){document.body.classList.toggle('modal-open',!!document.querySelector('dialog[open]'))}
function showFrame(i){if(!frames.length)return;index=(i+frames.length)%frames.length;const f=frames[index];frameSeconds=f.seconds;$('#lightbox-image').src='assets/'+f.id+'-hd.webp';$('#lightbox-image').alt=f.name;$('#lightbox-title').textContent=f.name;$('#lightbox-time').textContent=f.time;$('#lightbox-count').textContent=String(index+1).padStart(2,'0')+' / '+frames.length;$('#lightbox-download').href='assets/'+f.id+'-hd.webp';$('#lightbox-download').download=f.id+'.webp'}
async function openFrame(button){try{await dataReady;const seconds=Number(button.dataset.seconds);lightboxTrigger=button;showFrame(Math.max(0,frames.findIndex(f=>f.seconds===seconds)));lightbox.showModal();lock();}catch{button.querySelector('img')?.scrollIntoView({block:'center'})}}
function openFilm(seconds=0,trigger=null){const id=++requestId;lastTrigger=trigger||document.activeElement;if(lightbox.open)lightbox.close();if(!filmDialog.open)filmDialog.showModal();lock();const seekAndPlay=()=>{if(id!==requestId||!filmDialog.open)return;try{video.currentTime=Math.max(0,seconds)}catch{}video.play().catch(()=>{if(filmDialog.open){$('#film-status').hidden=false;$('#film-status').textContent='点击影片上的播放按钮开始观看。'}})};$('#film-status').hidden=true;if(!video.src){video.src=video.dataset.src;video.addEventListener('loadedmetadata',seekAndPlay,{once:true});video.load()}else if(video.readyState>=1){seekAndPlay()}else video.addEventListener('loadedmetadata',seekAndPlay,{once:true});}
$$('.image-button[data-seconds]').forEach(button=>button.addEventListener('click',()=>openFrame(button)));$$('[data-play-film]').forEach(button=>button.addEventListener('click',()=>openFilm(Number(button.dataset.filmTime)||0,button)));$('#lightbox-play').addEventListener('click',()=>openFilm(frameSeconds,lightboxTrigger));$('.lightbox-prev').addEventListener('click',()=>showFrame(index-1));$('.lightbox-next').addEventListener('click',()=>showFrame(index+1));
function closeDialog(dialog){if(dialog===filmDialog){requestId++;video.pause()}dialog.close()}
$$('[data-close-dialog]').forEach(button=>button.addEventListener('click',()=>closeDialog(button.closest('dialog'))));[lightbox,filmDialog].forEach(dialog=>{dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog(dialog)});dialog.addEventListener('cancel',()=>{if(dialog===filmDialog){requestId++;video.pause()}});dialog.addEventListener('close',()=>{if(dialog===filmDialog){requestId++;video.pause();lastTrigger?.focus({preventScroll:true})}else if(!filmDialog.open)lightboxTrigger?.focus({preventScroll:true});lock()})});
document.addEventListener('keydown',event=>{if(!lightbox.open)return;if(event.key==='ArrowLeft'){event.preventDefault();showFrame(index-1)}if(event.key==='ArrowRight'){event.preventDefault();showFrame(index+1)}});let touchX=null,touchY=null;$('.lightbox-stage').addEventListener('touchstart',event=>{if(event.touches.length!==1){touchX=null;return;}touchX=event.touches[0].clientX;touchY=event.touches[0].clientY},{passive:true});$('.lightbox-stage').addEventListener('touchend',event=>{if(touchX===null||!event.changedTouches.length)return;const dx=event.changedTouches[0].clientX-touchX,dy=event.changedTouches[0].clientY-touchY;if(Math.abs(dx)>50&&Math.abs(dx)>Math.abs(dy)*1.3)showFrame(index+(dx<0?1:-1));touchX=null},{passive:true});video.addEventListener('error',()=>{$('#film-status').hidden=false;$('#film-status').textContent='影片暂时无法加载，可以使用下方的快手原作品链接观看。'});
const menuButton=$('.menu-toggle'),menu=$('#mobile-menu');function closeMenu(){menu.hidden=true;menuButton.setAttribute('aria-expanded','false');menuButton.textContent='目录 ＋'}menuButton.addEventListener('click',()=>{const open=menu.hidden;menu.hidden=!open;menuButton.setAttribute('aria-expanded',String(open));menuButton.textContent=open?'关闭 ×':'目录 ＋'});$$('a',menu).forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!menu.hidden){closeMenu();menuButton.focus()}});document.addEventListener('click',e=>{if(!menu.hidden&&!menu.contains(e.target)&&!menuButton.contains(e.target))closeMenu()});matchMedia('(min-width:801px)').addEventListener('change',e=>{if(e.matches)closeMenu()});
let scheduled=false;function progress(){scheduled=false;const max=document.documentElement.scrollHeight-innerHeight;$('.reading-progress i').style.width=(max>0?Math.min(100,scrollY/max*100):0)+'%'}addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(progress)}},{passive:true});addEventListener('resize',progress);progress();dataReady.catch(()=>{});
})();
